
function pickRandom(arr = []) {
  if (!Array.isArray(arr) || arr.length === 0) return null
  return arr[Math.floor(Math.random() * arr.length)]
}

//antojitos 😂😂

async function feed() {
  try {
    const res = await fetch("https://raw.githubusercontent.com/fg-error/fg-team/refs/heads/main/img/feed.json")

    if (!res.ok) throw new Error(`HTTP ${res.status}`)

    const data = await res.json()
    const imageUrl = pickRandom(data)

    return  imageUrl 

  } catch (err) {
    console.error(err)
    return { imageUrl: null, error: true }
  }
}


module.exports = { feed }